104	      onFechar={() => setMenuAberto(false)}
105	    />
106	  );
107	
108	  if (!dados) {
109	    return (
110	      <View
111	        style={[
112	          styles.fill,
113	          { paddingTop: insets.top, backgroundColor: colors.bg },
114	        ]}
115	      >
116	        {topo}
117	        <View style={styles.margem}>
118	          {perfil.isPending ? (
119	            <ActivityIndicator style={styles.espera} color={colors.ink2} />
120	          ) : falhaParaTela(perfil.error).codigo === "usuario-nao-encontrado" &&
121	            proprio &&
122	            eu.data?.papeis.includes("instituicao") ? (
123	            <ContaDaInstituicao
124	              nome={eu.data.nomeDeExibicao}
125	              arroba={eu.data.arroba}
126	            />
127	          ) : falhaParaTela(perfil.error).codigo ===
128	            "usuario-nao-encontrado" ? (
129	            <EmptyState icon="user" title="Esse perfil não existe." />
130	          ) : (
131	            <ErrorState
132	              message={falhaParaTela(perfil.error).mensagem}
133	              onRetry={() => void perfil.refetch()}
134	            />
135	          )}
136	        </View>
137	        {menu}
138	      </View>
139	    );
140	  }
141	
142	  const cabecalho = (
143	    <View>
144	      {topo}
145	      <DadosDoPerfil perfil={dados} proprio={proprio} />
146	      {ehAluno && (
147	        <View
148	          style={[styles.abas, { borderBottomColor: colors.line }]}
149	          role="tablist"
150	        >
151	          {ABAS.map(({ aba: valor, icone, rotulo }) => {
152	            const ativa = aba === valor;
153	            return (
154	              <Pressable
155	                key={valor}
156	                role="tab"
157	                aria-selected={ativa}
158	                accessibilityLabel={rotulo}
159	                onPress={() => setAba(valor)}
160	                style={[styles.aba, ativa && { borderBottomColor: colors.ink }]}
161	              >
162	                <Icon
163	                  name={icone}
164	                  color={ativa ? colors.ink : colors.ink2}
165	                  size={24}
166	                />
167	              </Pressable>
168	            );
169	          })}
170	        </View>
171	      )}
172	    </View>
173	  );
174	
175	  const rodape = (
176	    <View style={{ height: espacamento.respiroAntesDaNavegacao }} />
177	  );
178	
179	  if (!ehAluno) {
180	    return (
181	      <View style={[styles.fill, { backgroundColor: colors.bg }]}>
182	        <FlatList
183	          style={{ backgroundColor: colors.bg }}
184	          contentContainerStyle={{ paddingTop: insets.top }}
185	          data={dados.professor?.turmas ?? []}
186	          keyExtractor={(turma) =>
187	            `${turma.materia}-${turma.curso}-${turma.semestre}`
188	          }
189	          ListHeaderComponent={
190	            <View>
191	              {cabecalho}
192	              <Text
193	                role="heading"
194	                style={[
195	                  textStyles.secao,
196	                  styles.margem,
197	                  styles.tituloDaSecao,
198	                  { color: colors.ink },
199	                ]}
200	              >
201	                Turmas neste semestre
202	              </Text>
203	            </View>
204	          }
205	          renderItem={({ item: turma }) => (
206	            <View
207	              style={[
208	                styles.margem,
209	                styles.turma,
210	                { borderBottomColor: colors.line },
211	              ]}
212	            >
213	              <Text style={[textStyles.secao, { color: colors.ink }]}>
214	                {turma.materia}
215	              </Text>
216	              <Text style={[textStyles.legenda, { color: colors.ink2 }]}>
217	                {`${turma.curso} · ${turma.semestre}`}
218	              </Text>
219	            </View>
220	          )}
221	          ListEmptyComponent={
222	            <Text
223	              style={[textStyles.corpo, styles.margem, { color: colors.ink2 }]}
224	            >
225	              Nenhuma turma no semestre vigente.
226	            </Text>
227	          }
228	          ListFooterComponent={rodape}
229	        />
230	        {menu}
231	      </View>
232	    );
233	  }
234	
235	  return (
236	    <View testID="perfil" style={[styles.fill, { backgroundColor: colors.bg }]}>
237	      {aba === "posts" ? (
238	        <FlatList
239	          key="posts"
240	          testID="grade"
241	          data={listaDePosts}
242	          keyExtractor={(post) => post.id}
243	          numColumns={3}
244	          columnWrapperStyle={{ gap: VAO }}
245	          contentContainerStyle={{ paddingTop: insets.top, gap: VAO }}
246	          renderItem={({ item }: { item: Post }) => (
247	            <CelulaDaGrade post={item} lado={lado} />
248	          )}
249	          ListHeaderComponent={cabecalho}
250	          ListEmptyComponent={
251	            posts.isPending ? (
252	              <ActivityIndicator style={styles.espera} color={colors.ink2} />
253	            ) : posts.isError ? (
254	              <View style={styles.margem}>
255	                <ErrorState
256	                  message={falhaParaTela(posts.error).mensagem}
257	                  onRetry={() => void posts.refetch()}
258	                />
259	              </View>
260	            ) : (
261	              <View style={styles.margem}>
262	                <EmptyState
263	                  icon="imagem"
264	                  title={
265	                    proprio ? "Você ainda não publicou." : "Nenhum post ainda."
266	                  }
267	                />
268	              </View>
269	            )
270	          }
271	          ListFooterComponent={
272	            <View>
273	              {posts.isFetchingNextPage && (
274	                <ActivityIndicator color={colors.ink2} />
275	              )}
276	              {rodape}
277	            </View>
278	          }
279	          onEndReachedThreshold={0.5}
280	          onEndReached={() => {
281	            if (posts.hasNextPage && !posts.isFetchingNextPage) {
282	              void posts.fetchNextPage();
283	            }
284	          }}
285	        />
286	      ) : (
287	        <FlatList
288	          key={aba}
289	          data={itensDePremio}
290	          keyExtractor={(item) => item.codigo}
291	          contentContainerStyle={{ paddingTop: insets.top }}
292	          renderItem={({ item }) => (
293	            <View style={styles.margem}>
294	              <LinhaDePremio item={item} />
295	            </View>
296	          )}
297	          ListHeaderComponent={cabecalho}
298	          ListEmptyComponent={
299	            premios.isPending ? (
300	              <ActivityIndicator style={styles.espera} color={colors.ink2} />
301	            ) : premios.isError ? (
302	              <View style={styles.margem}>
303	                <ErrorState
304	                  message={falhaParaTela(premios.error).mensagem}
305	                  onRetry={() => void premios.refetch()}
306	                />
307	              </View>
308	            ) : (
309	              <View style={styles.margem}>
310	                <EmptyState
311	                  icon={aba === "medalhas" ? "fita" : "taca"}
312	                  title={
313	                    aba === "medalhas"
314	                      ? "Nenhuma medalha ainda."
315	                      : "Nenhum troféu ainda."
316	                  }
317	                />
318	              </View>
319	            )
320	          }
321	          ListFooterComponent={rodape}
322	        />
323	      )}
324	      {menu}
325	    </View>
326	  );
327	}
328	
329	// O cabeçalho do perfil: avatar, números, nome, linha de curso, botões.
330	function DadosDoPerfil({
331	  perfil,
332	  proprio,
333	}: {
334	  perfil: Perfil;
335	  proprio: boolean;
336	}) {
337	  const { colors } = useTheme();
338	  const router = useRouter();
339	  const eu = useEu();
340	  const seguir = useSeguir(perfil.id);
341	  const ehAluno = perfil.papel === "aluno";
342	  const papeis = eu.data?.papeis ?? [];
343	  const leitorProfessor = papeis.includes("professor");
344	  const turmas = useTurmasEmComum(
345	    perfil.id,
346	    !proprio && ehAluno && leitorProfessor,
347	  );
348	  const [concederEm, setConcederEm] = useState<string | null>(null);
349	  const [escolhendoTurma, setEscolhendoTurma] = useState(false);
350	  const [aviso, setAviso] = useState<string | null>(null);
351	
352	  // Quem segue (produto.md 6.3): aluno segue aluno; professor, só os alunos dele. Quem já
353	  // segue sempre pode deixar de seguir.
354	  const podeSeguir =
355	    !proprio &&
356	    ehAluno &&
357	    (perfil.euSigo ||
358	      papeis.includes("aluno") ||
359	      (leitorProfessor && turmas.length > 0));
360	
361	  const descricao = [
362	    perfil.curso,
363	    perfil.semestre ? `${perfil.semestre}º semestre` : null,
364	    perfil.exAluno ? "Ex-aluno" : null,
365	    perfil.ra ? `RA ${perfil.ra}` : null,
366	    perfil.posicao ? `#${formatarNumero(perfil.posicao)}` : null,
367	  ]
368	    .filter(Boolean)
369	    .join(" · ");
370	
371	  return (
372	    <View style={[styles.margem, styles.cabecalho]}>
373	      <View style={styles.linhaDoTopo}>
374	        <Avatar
375	          nome={perfil.nomeDeExibicao}
376	          foto={perfil.foto?.grade}
377	          size={84}
378	          anel={proprio && ehAluno}
379	        />
380	        {ehAluno && (
381	          <Pontos
382	            pontos={perfil.pontos ?? 0}
383	            posicao={perfil.posicao}
384	            onPress={
385	              proprio
386	                ? () => router.push("/rankings?visao=historico")
387	                : undefined
388	            }
389	          />
390	        )}
391	        {ehAluno && <Contagem numero={perfil.seguidores} rotulo="seguidores" />}
392	        <Contagem numero={perfil.seguindo} rotulo="seguindo" />
393	      </View>
394	
395	      <View style={styles.quem}>
396	        <Text style={[textStyles.titulo, { color: colors.ink }]}>
397	          {perfil.nomeDeExibicao}
398	        </Text>
399	        <Text
400	          testID="arroba"
401	          style={[textStyles.legenda, { color: colors.ink2 }]}
402	        >
403	          {perfil.arroba}
404	        </Text>
405	        {descricao !== "" && (
406	          <Text style={[textStyles.corpo, { color: colors.ink2 }]}>
407	            {descricao}
408	          </Text>
409	        )}
410	        {perfil.professor && (
411	          <Text style={[textStyles.corpo, { color: colors.ink2 }]}>
412	            {`Professor · ${formatarNumero(perfil.professor.medalhasConcedidas)} ${
413	              perfil.professor.medalhasConcedidas === 1
414	                ? "medalha concedida"
415	                : "medalhas concedidas"
416	            }`}
417	          </Text>
418	        )}
419	      </View>
420	
421	      <View style={styles.botoes}>
422	        {proprio && (
423	          <View style={styles.botao}>
424	            <Button
425	              label="Editar perfil"
426	              variant="secondary"
427	              onPress={() => router.push("/editar-perfil")}
428	            />
429	          </View>
430	        )}
431	        {podeSeguir && (
432	          <View style={styles.botao}>
433	            <Button
434	              label={
435	                seguir.isPending
436	                  ? "Aguarde..."
437	                  : perfil.euSigo
438	                    ? "Seguindo"
439	                    : "Seguir"
440	              }
441	              variant={perfil.euSigo ? "secondary" : "primary"}
442	              disabled={seguir.isPending}
443	              accessibilityLabel={
444	                perfil.euSigo
445	                  ? `Deixar de seguir ${perfil.nomeDeExibicao}`
446	                  : `Seguir ${perfil.nomeDeExibicao}`
447	              }
448	              onPress={() => {
449	                setAviso(null);
450	                seguir.mutate(!perfil.euSigo, {
451	                  onError: (erro) => setAviso(falhaParaTela(erro).mensagem),
452	                });
453	              }}
454	            />
455	          </View>
456	        )}
457	        {turmas.length > 0 && (
458	          <View style={styles.botao}>
459	            <Button
460	              label="Conceder medalha"
461	              variant="secondary"
462	              onPress={() =>
463	                turmas.length === 1
464	                  ? setConcederEm(turmas[0]!.id)
465	                  : setEscolhendoTurma(true)
466	              }
467	            />
468	          </View>
469	        )}
470	      </View>
471	
472	      {escolhendoTurma &&
473	        turmas.map((turma) => (
474	          <Button
475	            key={turma.id}
476	            label={`Em ${turma.materia}`}
477	            variant="secondary"
478	            onPress={() => {
479	              setEscolhendoTurma(false);
480	              setConcederEm(turma.id);
481	            }}
482	          />
483	        ))}
484	      {aviso && <AvisoDeErro mensagem={aviso} />}
485	
486	      {concederEm && (
487	        <ModalDeConcessao
488	          turmaId={concederEm}
489	          aluno={{ id: perfil.id, nomeDeExibicao: perfil.nomeDeExibicao }}
490	          onFechar={() => setConcederEm(null)}
491	          onConcedida={(mensagem) => {
492	            setConcederEm(null);
493	            setAviso(mensagem);
494	          }}
495	        />
496	      )}
497	    </View>
498	  );
499	}
500	
501	// Os pontos acumulados e a posição no histórico geral, coerente com eles (pergunta 4 do
502	// passo 11): "15.020 / pts · #29 ›". No próprio perfil, tocar abre o ranking nesse chip
503	// (produto.md 6.5); no de outra pessoa, só mostra. Sem posição ainda, só os pontos.
504	function Pontos({
505	  pontos,
506	  posicao,
507	  onPress,
508	}: {
509	  pontos: number;
510	  posicao: number | null;
511	  onPress?: () => void;
512	}) {
513	  const { colors } = useTheme();
514	  const legenda = posicao ? `pts · #${formatarNumero(posicao)}` : "pts";
515	  const conteudo = (
516	    <>
517	      <Text style={[textStyles.titulo, { color: colors.ink }]}>
518	        {formatarNumero(pontos)}
519	      </Text>
520	      <View style={styles.legendaDosPontos}>
521	        <Text
522	          style={[textStyles.legenda, styles.forte, { color: colors.goldText }]}
523	        >
524	          {legenda}
525	        </Text>
526	        {onPress && <Icon name="avancar" color={colors.goldText} size={14} />}
527	      </View>
528	    </>
529	  );
530	
531	  return onPress ? (
532	    <Pressable
533	      testID="pontos-do-perfil"
534	      role="link"
535	      accessibilityLabel={
536	        posicao
537	          ? `${pontos} pontos, posição ${posicao}. Abrir rankings`
538	          : `${pontos} pontos. Abrir rankings`
539	      }
540	      onPress={onPress}
541	      style={({ pressed }) => [
542	        styles.pontos,
543	        { backgroundColor: colors.surface },
544	        pressed && { opacity: interacao.opacidadePressionado },
545	      ]}
546	    >
547	      {conteudo}
548	    </Pressable>
549	  ) : (
550	    <View
551	      testID="pontos-do-perfil"
552	      style={[styles.pontos, { backgroundColor: colors.surface }]}
553	    >
554	      {conteudo}
555	    </View>
556	  );
557	}
558	
559	function Contagem({ numero, rotulo }: { numero: number; rotulo: string }) {
560	  const { colors } = useTheme();
561	  return (
562	    <View
563	      style={styles.contagem}
564	      accessible
565	      accessibilityLabel={`${numero} ${rotulo}`}
566	    >
567	      <Text style={[textStyles.titulo, { color: colors.ink }]}>
568	        {formatarNumero(numero)}
569	      </Text>
570	      <Text style={[textStyles.legenda, { color: colors.ink2 }]}>{rotulo}</Text>
571	    </View>
572	  );
573	}
574	
575	const styles = StyleSheet.create({
576	  fill: { flex: 1 },
577	  margem: { paddingHorizontal: espacamento.margemLateral },
578	  topo: {
579	    flexDirection: "row",
580	    alignItems: "center",
581	    justifyContent: "space-between",
582	    paddingVertical: 8,
583	  },
584	  botaoDeIcone: {
585	    width: tamanhos.alvoDeToque,
586	    height: tamanhos.alvoDeToque,
587	    alignItems: "center",
588	    justifyContent: "center",
589	    marginRight: -10,
590	  },
591	  espera: { marginTop: 32 },
592	  cabecalho: { gap: 16, paddingTop: 8, paddingBottom: 16 },
593	  linhaDoTopo: { flexDirection: "row", alignItems: "center", gap: 12 },
594	  pontos: {
595	    borderRadius: raios.cardMenor,
596	    paddingHorizontal: 12,
597	    paddingVertical: 8,
598	  },
599	  forte: { fontWeight: "700" },
600	  legendaDosPontos: { flexDirection: "row", alignItems: "center", gap: 2 },
601	  contagem: { flex: 1, alignItems: "center" },
602	  quem: { gap: 2 },
603	  botoes: { flexDirection: "row", gap: 8 },
604	  botao: { flex: 1 },
605	  abas: { flexDirection: "row", borderBottomWidth: 1 },
606	  aba: {
607	    flex: 1,
608	    alignItems: "center",
609	    paddingVertical: 12,
610	    borderBottomWidth: 2,
611	    borderBottomColor: "transparent",
612	  },
613	  tituloDaSecao: { paddingTop: 8, paddingBottom: 4 },
614	  turma: { paddingVertical: 12, borderBottomWidth: 1, gap: 2 },
615	});
